<style>
    /* ---- 0. Global ---- */
    *{box-sizing:border-box;margin:0;padding:0;font-family:"Cormorant Garamond",serif;}

    h2{
        font-size: 2.4rem;
        line-height: 1.2;
        font-weight: 700;
        color: var(--orange);
        margin-bottom: 1rem;
        text-align: left;
    }

    /* ---- 1. Heading ---- */
    .heading {
        background-color: var(--orange);
        text-align: left;
        border-radius: 16px;
        padding: 40px 0 40px 40px;
        margin: 30px 0 40px 0;
        color: #fff;
    }

    .heading-container {
        display: flex;
        justify-content: space-between;
        width: 97%;
        max-width: 1000px;
    }

    #h-left {
        width: 50%;
    }

    #h-right {
        display: flex;
        align-items: flex-end;
        justify-content: space-between;
        padding: 20px;
        margin: 20px 0;
        width: 45%;
    }

    .heading h1 {
        font-size: 3.3em;
        margin-bottom: 20px;
        font-family: "ABeeZee", sans-serif;
    }
    
    .first-svg {
        transform: translateY(-90%);
    }
    
    .second-svg {
        align-self: flex-end;
        transform: translateY(45%);
    }

    .heading p {
        font-size: 1.2em;
        line-height: 1.5;
        color: var(--dark-gray);
    }

    /* ---- 2. Why early prevention ---- */
    .why-e-a {
        display: flex;
        justify-content: center;
        align-items: center;
        width: 100%;
        margin-top: 2rem;
    }
    
    .why-e-a-container {
        display: flex;
        justify-content: center;
        align-items: center;
        width: 90%;
        max-width: 1000px;
        margin-bottom: 2rem;
    }

    .w-left {
        width: 51%;
        padding-right: 20px;
        line-height: 1.5;
    }

    .w-left p {
        font-size: 1.3rem;
    }

    .w-right {
        width: 50%;
        display: flex;
        justify-content: space-between;
        gap: 20px;
        align-items: center;
        position: relative;
        padding: 0 25px;
    }

    .first-svg-w {
        position: absolute;
        top: 0;
        left: 0;
        transform: translateY(-50%);
    }

    .second-svg-w {
        position: absolute;
        right: 0;
        bottom: 0;
        transform: translateY(50%);
    }

    .w-right img {
        max-width: 100%;
        height: auto;
        border-radius: 16px;
    }

    /* ---- 3. Main section ---- */
    .main-section {
        width: 90%;
        max-width: 1000px;
        position: relative;
        margin-bottom: 50px;
        font-size: larger;
    }

    .main-section h4 {
        font-size: 1.5rem !important;
    }

    .main-section p, li {
        font-size: 1.25rem !important;
    }

    .icon {
        width: 50px;
        height: 50px;
        background: #ff9d6b;
        border-radius: 50%;
        display: flex;
        align-items: center;
        justify-content: center;
        color: white;
        font-size: 1.4rem;
        flex-shrink: 0;
    }

    .content-card {
        background: var(--orange-light);
        border-radius: 15px;
        padding: 40px;
        box-shadow: 0 10px 20px 0 rgba(0, 0, 0, 0.142);
        margin-bottom: 20px;
    }

    .age-highlight {
        background: var(--background);
        border-radius: 10px;
        padding: 25px;
        margin-bottom: 25px;
        border-left: 5px solid #ff9d6b;
        box-shadow: 0 5px 12px rgba(0, 0, 0, 0.1);
    }

    .age-highlight strong {
        color: var(--orange);
        font-family: 'ABeeZee', sans-serif;
        font-size: 1.5rem;
        display: block;
        margin-bottom: 10px;
    }


    /* Евентуално може да се ползва
     .important-note {
        background: #f8f9fa;
        border-radius: 10px;
        padding: 20px;
        margin: 25px 0;
        border-left: 4px solid #ff9d6b;
        } 
        
        .important-note h4 {
            color: #ff9d6b;
            margin-bottom: 10px;
            font-size: 1.1rem;
        } */

    .benefits-box {
        background: var(--background);
        border-radius: 10px;
        border: 3px solid var(--orange);
        padding: 25px;
        margin: 25px 0;
    }

    .benefits-box h4 {
        color: var(--orange);
        margin-bottom: 15px;
    }

    .emphasis {
        background: var(--orange-dark);
        padding: 15px;
        border-radius: 8px;
        border-left: 4px solid #ffb347;
        margin-top: 15px;
        font-style: italic;
        font-weight: 600;
    }

    .outcomes-section h4 {
        color: var(--orange);
        margin-bottom: 20px;
    }

    .outcomes-grid {
        display: grid;
        grid-template-columns: repeat(auto-fit, minmax(250px, 1fr));
        gap: 20px;
    }

    .outcome-item {
        display: flex;
        align-items: flex-start;
        background: var(--background);
        padding: 20px;
        border: 2px solid var(--orange);
        border-radius: 10px;
        gap: 15px;
    }

    .outcome-icon {
        font-size: 1.5rem;
        flex-shrink: 0;
    }

    /* ---- 3.2. Main section ---- */
    .foundation-section {
        background: linear-gradient(135deg, #fff5f0, #ffe8d9);
        border-radius: 10px;
        padding: 25px;
        margin-top: 25px;
    }

    .foundation-section h4 {
        color: #ff9d6b;
        margin-bottom: 15px;
    }

    .services-grid {
        display: flex;
        flex-wrap: wrap;
        justify-content: center;
        align-items: flex-start;
        gap: 25px;
        margin-top: 25px;
    }

    .services-grid > * {
        width: 210px;
    }

    .service-item {
        display: flex;
        align-items: center;
        justify-content: center;
        flex-direction: column;
        text-align: center;
        width: 230px;
        margin: 0.6rem;
        border-radius: 10px;
        background-color: var(--orange);
        box-shadow: 0 4px 8px rgba(0, 0, 0, 0.1);
        transition: transform 0.3s, box-shadow 0.3s;
    }

    .service-item svg {
        width: 110px;
        height: 110px;
    }

    .more-btn {
        margin: 0.5rem 0;
        font-size: 1rem;
        font-weight: 500;
        color: black;
        background-color: var(--green-button);
        border: 2px solid black;
        padding: 0.4rem 0.8rem;
        border-radius: 20px;
        cursor: pointer;
        transition: all 0.3s ease;
        text-decoration: none;
        }
        .more-btn:hover {
        background-color: var(--green-secondory);
        color: white;
        }

        .less-btn {
        margin: 0.5rem 0;
        font-size: 1rem;
        font-weight: 500;
        color: white;
        background-color: var(--green-secondory);
        border: 2px solid black;
        padding: 0.4rem 0.8rem;
        border-radius: 20px;
        cursor: pointer;
        transition: all 0.3s ease;
        text-decoration: none;
        }
        .less-btn:hover {
        background-color: var(--green-button);
        color: black;
        }

    /* .service-icon {
        font-size: 2rem;
        display: block;
        margin-bottom: 15px;
    }

    .service-item h4 {
        color: var(--orange);
        margin-bottom: 10px;
        font-size: 1.4rem !important;
    }

    .service-icon p {
        font-size: 1.1rem;
        color: #555;
        line-height: 1.4;
    } */

    .family-benefits {
        margin-top: 25px;
    }

    .benefit-item {
        display: flex;
        align-items: flex-start;
        gap: 20px;
        padding: 20px;
        margin-bottom: 15px;
        background: #f8f9fa;
        border-radius: 12px;
        transition: background-color 0.3s ease;
    }

    .benefit-item:hover {
        background: #e9ecef;
    }

    .benefit-icon {
        font-size: 1.8rem;
        flex-shrink: 0;
    }

    .benefit-item h4 {
        color: #ff9d6b;
        margin-bottom: 8px;
        font-size: 1.1rem;
    }

    .key-points {
        list-style: none;
        padding-left: 0;
        margin: 15px 0;
    }

    .key-points li {
        margin-bottom: 12px;
        padding-left: 30px;
        position: relative;
    }

    .key-points li::before {
        content: '✓';
        position: absolute;
        left: 0;
        color: #ff9d6b;
        font-weight: bold;
        font-size: 1.2rem;
    }

    .section-intro {
        font-size: 1.3rem;
        margin-bottom: 25px;
        color: #555;
        line-height: 1.5;
    }

    .intro-text {
        font-size: 1.3rem;
        color: #555;
        line-height: 1.5;
    }

    .key-message-section {
        background: linear-gradient(135deg, #ff9d6b, #ffb380);
        color: white;
        border-radius: 15px;
        padding: 50px;
        text-align: center;
        margin: 50px 0;
        position: relative;
        overflow: hidden;
    }

    .key-message-section::before {
        content: '';
        position: absolute;
        top: -20px;
        right: -20px;
        width: 100px;
        height: 100px;
        background: rgba(255, 255, 255, 0.1);
        border-radius: 50%;
    }

    .key-message-content {
        position: relative;
        z-index: 2;
    }

    .key-message-section h3 {
        font-size: 2.2rem;
        margin-bottom: 20px;
        font-weight: 700;
    }

    .key-text {
        font-size: 1.3rem;
        margin-bottom: 25px;
        opacity: 0.95;
        line-height: 1.5;
    }

    /* ---- Media query - 955 ---- */
    @media screen and (max-width: 955px) {
