        .w-left {
            width: 45%;
        }

        .w-left p {
            font-size: 1.2rem;
        }

        .w-right {
            width: 55%;
        }
    }

    /* ---- Media query - 755 ---- */
    @media screen and (max-width: 755px) {
        /* ---- 1. Heading ---- */
        .heading {
            padding: 35px 35px 10px 35px;
            margin: 20px 0 !important;
            text-align: center;
            margin: 0 auto;
        }
        
        .heading-container {
            flex-direction: column;
        }
        
        #h-left, #h-right {
            width: 100%;
            text-align: center;
